import{c as r,Q as t,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Claude Mythos Preview System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-mythos-preview-system-card","title":"Claude Mythos Preview System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2026-04-07T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-mythos-preview-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2026-04-07-claude-mythos-preview-system-card.md","filePath":"research/papers/2026-04-07-claude-mythos-preview-system-card.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-04-07-claude-mythos-preview-system-card.md"};function i(l,e,n,c,d,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="claude-mythos-preview-system-card" tabindex="-1">Claude Mythos Preview System Card <a class="header-anchor" href="#claude-mythos-preview-system-card" aria-label="Permalink to &quot;Claude Mythos Preview System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-mythos-preview-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-mythos-preview-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%20Mythos%20Preview%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: April 7, 2026</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Mythos Preview 是 Anthropic 當時最強 frontier 模型，但因 <strong>網路安全能力過強</strong>而<strong>未做一般商用釋出</strong>——改作為有限夥伴的防禦性 cybersecurity 計畫使用。官方強調限制存取的決策由 cyber 能力驅動，而非 RSP 硬性要求。是首份「無一般商用 GA」即公開的 system card。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Mythos Preview</strong>：最強 frontier 模型；非 GA，限定夥伴防禦性 cyber 用途。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>93.9%</strong>。</li><li><strong>SWE-bench Pro</strong>：<strong>77.8%</strong>。</li><li><strong>Terminal-Bench 2.0</strong>：<strong>82.0%</strong>。</li><li><strong>USAMO 2026</strong>：<strong>97.6%</strong>。</li><li><strong>Cybench</strong>：飽和（<strong>100%</strong> pass rate）。</li><li><strong>CyberGym</strong>：<strong>0.83</strong>（由前代 0.67 提升）。</li><li><strong>自製 Firefox 147 zero-day exploitation benchmark</strong>：<strong>84%</strong> 成功率。</li><li><strong>AI Safety Level</strong>：公開文件未明定正式檔位；二手分析提及實務上以 ASL-3 或更高（部分提及 ASL-4 條件供夥伴存取），<strong>正式 tier 官方留白</strong>——保守標註，不臆斷。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li><strong>不釋出決策</strong>：cyber 能力（尤其 zero-day exploitation 達 84%）使官方選擇不 GA，改走防禦夥伴計畫——能力治理優先於商業化的明確案例。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong>cyber 域路由紀律</strong>：CLAUDE.md 註明「Fable 對 cyber/bio prompt silent fallback → Opus，該域直接指定 Opus」——Mythos 級 cyber 能力正是此類治理的源頭；本庫對 cyber/bio 任務應顯式指定模型、不賭路由。</li><li><strong>ceiling 但不可用</strong>：Mythos Preview 是 <code>pilot</code>（tier=frontier，原 <code>fable-pilot</code>）/<code>pilot</code>（tier=ceiling，原 <code>opus-pilot</code>） 之上的「理論天花板」參照，但非可調用模型——model-selection 時不納入可選清單。</li><li><strong>能力治理 ↔ 生產紅線</strong>：與 core.md「不可逆/高風險動作須 gate」同精神——能力越強，部署越須前置防護。⚠️ 域外：本庫無 cyber offensive 任務，此卡為背景認知而非操作依據。</li></ul>',17)])])}const u=r(s,[["render",i]]);export{m as __pageData,u as default};
